<script setup lang="ts">
import { computed, onUnmounted, ref } from 'vue';
import { useAuthStore } from '@/stores/auth.store';
import { apiClient } from '@/services/api/apiClient';

const authStore = useAuthStore();
const profile = computed(() => authStore.profile || {});
const form = ref({ display_name: profile.value.display_name || '' });
const savingProfile = ref(false);
const uploadingAvatar = ref(false);
const feedback = ref('');
const errorMessage = ref('');
const fileInput = ref<HTMLInputElement | null>(null);
const previewUrl = ref('');

const avatarUrl = computed(() => previewUrl.value || profile.value.avatar_url || `https://api.dicebear.com/9.x/shapes/svg?seed=${profile.value.username || 'lunu'}&backgroundColor=193a31`);
const initials = computed(() => (profile.value.display_name || profile.value.username || 'L').slice(0, 1).toUpperCase());

const saveProfile = async () => {
  savingProfile.value = true; feedback.value = ''; errorMessage.value = '';
  try {
    const res: any = await apiClient.patch('/auth/profile', { display_name: form.value.display_name });
    if (res.success) { authStore.profile = res.data; feedback.value = 'Hồ sơ đã được cập nhật.'; }
  } catch (error: any) { errorMessage.value = error.message || 'Không thể cập nhật hồ sơ.'; }
  finally { savingProfile.value = false; }
};

const chooseAvatar = () => fileInput.value?.click();
const uploadAvatar = async (event: Event) => {
  const file = (event.target as HTMLInputElement).files?.[0];
  if (!file) return;
  if (!file.type.startsWith('image/') || file.size > 5 * 1024 * 1024) { errorMessage.value = 'Ảnh phải là file hình ảnh và nhỏ hơn 5 MB.'; return; }
  if (previewUrl.value) URL.revokeObjectURL(previewUrl.value);
  previewUrl.value = URL.createObjectURL(file);
  uploadingAvatar.value = true; feedback.value = ''; errorMessage.value = '';
  const body = new FormData(); body.append('avatar', file, file.name);
  try {
    const res: any = await apiClient.post('/auth/profile/avatar', body, { headers: { 'Content-Type': 'multipart/form-data' } });
    if (res.success) { authStore.profile = res.data; URL.revokeObjectURL(previewUrl.value); previewUrl.value = ''; feedback.value = 'Ảnh đại diện mới đã được lưu. Ảnh cũ đã được dọn khỏi Storage.'; }
  } catch (error: any) { errorMessage.value = error.message || 'Không thể tải ảnh lên.'; if (previewUrl.value) { URL.revokeObjectURL(previewUrl.value); previewUrl.value = ''; } }
  finally { uploadingAvatar.value = false; if (fileInput.value) fileInput.value.value = ''; }
};

onUnmounted(() => { if (previewUrl.value) URL.revokeObjectURL(previewUrl.value); });
</script>

<template>
  <div class="page-frame profile-page">
    <div class="profile-heading"><div><div class="eyebrow">Member identity · LuNu Club</div><h1 class="page-title mb-2">Hồ sơ của bạn</h1><p>Quản lý danh tính, ảnh đại diện và dấu ấn cá nhân trên bàn chơi.</p></div><router-link to="/" class="btn btn-quiet"><i class="bi bi-arrow-left me-2"></i>Về tổng quan</router-link></div>
    <div v-if="feedback" class="profile-feedback success"><i class="bi bi-check-circle me-2"></i>{{ feedback }}</div><div v-if="errorMessage" class="profile-feedback error"><i class="bi bi-exclamation-triangle me-2"></i>{{ errorMessage }}</div>
    <div class="profile-layout mt-4">
      <aside class="profile-card glass-panel"><div class="profile-card-glow"></div><div class="profile-avatar-wrap"><img :src="avatarUrl" alt="Ảnh đại diện" class="profile-avatar"><button class="avatar-edit" :disabled="uploadingAvatar" @click="chooseAvatar"><i :class="uploadingAvatar ? 'bi bi-arrow-repeat spin' : 'bi bi-camera-fill'"></i></button><span class="member-online"><span></span> Đang hoạt động</span></div><div class="profile-name"><h2>{{ profile.display_name || initials }}</h2><p>@{{ profile.username || 'member' }}</p></div><div class="profile-level"><div class="level-row"><span>Level {{ profile.level || 1 }}</span><strong>{{ profile.xp || 0 }} XP</strong></div><div class="level-track"><span :style="{ width: `${Math.min(100, ((profile.xp || 0) % 1000) / 10)}%` }"></span></div><small>Hình ảnh được lưu theo tên user + timestamp và tự dọn khi thay ảnh.</small></div><div class="profile-badges"><span><i class="bi bi-shield-check"></i> Thành viên xác thực</span><span><i class="bi bi-stars"></i> LuNu Club</span></div><input ref="fileInput" type="file" accept="image/png,image/jpeg,image/webp,image/gif" class="d-none" @change="uploadAvatar"></aside>
      <main class="profile-main"><section class="settings-panel glass-panel"><div class="section-title"><div><div class="eyebrow">Public identity</div><h2>Thông tin hiển thị</h2><p>Đây là thông tin người chơi khác nhìn thấy trong phòng.</p></div><span class="secure-mark"><i class="bi bi-lock-fill"></i> Bảo mật</span></div><form class="profile-form" @submit.prevent="saveProfile"><label>Tên hiển thị<input v-model="form.display_name" class="form-control" minlength="2" maxlength="40" required><small>2–40 ký tự. Username không thể đổi để bảo toàn lịch sử ván.</small></label><label>Username<div class="locked-field"><i class="bi bi-at"></i><span>{{ profile.username }}</span><i class="bi bi-lock-fill ms-auto"></i></div><small>Định danh cố định của tài khoản.</small></label><div class="form-actions"><span class="form-hint"><i class="bi bi-info-circle me-1"></i>Thay đổi sẽ đồng bộ cho các bàn đang mở.</span><button class="btn btn-gold" type="submit" :disabled="savingProfile">{{ savingProfile ? 'Đang lưu...' : 'Lưu thay đổi' }}<i class="bi bi-arrow-right ms-2"></i></button></div></form></section><section class="settings-panel glass-panel"><div class="section-title"><div><div class="eyebrow">Avatar lifecycle</div><h2>Ảnh đại diện</h2><p>Ảnh mới được đặt tên theo username + thời gian. Ảnh cũ được xóa sau khi cập nhật thành công.</p></div></div><div class="avatar-upload-row"><div class="mini-avatar"><img :src="avatarUrl" alt="Preview"></div><div class="upload-copy"><strong>Chọn ảnh mới</strong><small>PNG, JPG, WEBP hoặc GIF · tối đa 5 MB</small><button class="text-action" :disabled="uploadingAvatar" @click="chooseAvatar">{{ uploadingAvatar ? 'Đang tải lên...' : 'Chọn file từ thiết bị' }} <i class="bi bi-upload"></i></button></div><div class="storage-policy"><i class="bi bi-recycle"></i><span><strong>Storage sạch</strong><small>Không giữ bản cũ</small></span></div></div></section><section class="stats-panel"><div class="stat-item glass-panel"><i class="bi bi-controller"></i><div><strong>0</strong><small>Ván đã chơi</small></div></div><div class="stat-item glass-panel"><i class="bi bi-trophy"></i><div><strong>0%</strong><small>Tỷ lệ thắng</small></div></div><div class="stat-item glass-panel"><i class="bi bi-award"></i><div><strong>0</strong><small>Huy hiệu</small></div></div></section></main>
    </div>
  </div>
</template>

<style scoped>
