mary)}.level-track{height:5px;margin:8px 0;border-radius:9px;background:#264139;overflow:hidden}.level-track span{display:block;height:100%;border-radius:inherit;background:linear-gradient(90deg,var(--gv-secondary),var(--gv-primary))}.profile-level small{display:block;color:var(--gv-text-dim);font-size:.52rem;line-height:1.5}.profile-badges{display:flex;flex-direction:column;gap:7px;margin-top:18px;text-align:left}.profile-badges span{padding:8px 9px;color:var(--gv-text-muted);border-radius:9px;background:rgba(255,255,255,.035);font-size:.56rem}.profile-badges i{width:17px;color:var(--gv-primary);margin-right:5px;text-align:center}.profile-main{display:flex;flex-direction:column;gap:15px}.settings-panel{padding:22px}.section-title{display:flex;align-items:flex-start;justify-content:space-between;gap:15px}.section-title h2{font-size:1rem;font-weight:800;margin:6px 0}.section-title p{color:var(--gv-text-muted);font-size:.64rem;line-height:1.5;margin:0}.secure-mark{color:var(--gv-accent-success);font-size:.55rem}.profile-form{margin-top:22px;max-width:650px}.profile-form label{display:block;color:var(--gv-text-muted);font-size:.63rem;font-weight:700}.profile-form label+label{margin-top:15px}.profile-form input{margin-top:7px}.profile-form small{display:block;color:var(--gv-text-dim);font-size:.53rem;font-weight:500;margin-top:6px}.locked-field{display:flex;align-items:center;gap:7px;margin-top:7px;padding:10px 12px;border:1px solid rgba(255,255,255,.07);border-radius:10px;color:var(--gv-text-muted);background:rgba(255,255,255,.025);font:500 .65rem 'DM Mono',monospace}.locked-field i{color:var(--gv-text-dim)}.form-actions{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-top:23px}.form-hint{color:var(--gv-text-dim);font-size:.55rem}.form-hint i{color:var(--gv-secondary)}.avatar-upload-row{display:flex;align-items:center;gap:14px;margin-top:20px;padding:13px;border:1px solid rgba(255,255,255,.07);border-radius:13px;background:rgba(255,255,255,.025)}.mini-avatar{width:52px;height:52px;overflow:hidden;border-radius:15px}.mini-avatar img{width:100%;height:100%;object-fit:cover}.upload-copy{flex:1}.upload-copy strong,.upload-copy small{display:block}.upload-copy strong{font-size:.68rem}.upload-copy small{color:var(--gv-text-muted);font-size:.55rem;margin-top:4px}.text-action{padding:0;margin-top:8px;border:0;color:var(--gv-primary);background:transparent;font-size:.57rem;font-weight:800}.storage-policy{display:flex;align-items:center;gap:8px;padding-left:14px;border-left:1px solid rgba(255,255,255,.08);color:var(--gv-secondary)}.storage-policy i{font-size:1.1rem}.storage-policy strong,.storage-policy small{display:block}.storage-policy strong{color:var(--gv-text-main);font-size:.59rem}.storage-policy small{color:var(--gv-text-muted);font-size:.52rem;margin-top:3px}.stats-panel{display:grid;grid-template-columns:repeat(3,1fr);gap:13px}.stat-item{display:flex;align-items:center;gap:10px;padding:15px}.stat-item>i{color:var(--gv-primary);font-size:1rem}.stat-item strong,.stat-item small{display:block}.stat-item strong{font-size:1rem}.stat-item small{color:var(--gv-text-muted);font-size:.55rem;margin-top:3px}.spin{animation:spin 1s linear infinite}@keyframes spin{to{transform:rotate(360deg)}}@media(max-width:800px){.profile-layout{grid-template-columns:1fr}.profile-card{max-width:none}.profile-heading{display:block}.profile-heading .btn{margin-top:15px}.avatar-upload-row{align-items:flex-start;flex-wrap:wrap}.storage-policy{width:100%;padding:10px 0 0;border-top:1px solid rgba(255,255,255,.08);border-left:0}.form-actions{align-items:flex-start;flex-direction:column}.form-actions .btn{width:100%}}@media(max-width:480px){.stats-panel{grid-template-columns:1fr}.profile-page{padding-top:22px}}
</style>
